"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["47309"],{39365(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.secao_reservada","status":422,"titulo":"A se\xe7\xe3o dos dados b\xe1sicos do candidato \xe9 reservada"},"descricao":{"codigo":"uniplus.estrutura_formulario.secao_reservada","requisitos":["UNI-REQ-0151"],"oQueAconteceu":["O formul\xe1rio de inscri\xe7\xe3o tem uma se\xe7\xe3o reservada, `DADOS_BASICOS`, em que o sistema coloca o conjunto b\xe1sico de dados do candidato (UNI-REQ-0151). Um item ou um grupo que n\xe3o \xe9 desse conjunto aponta para essa se\xe7\xe3o em `paginaCodigo`. A se\xe7\xe3o \xe9 s\xf3 dos dados b\xe1sicos, e as demais perguntas ficam em outras se\xe7\xf5es. A mensagem \xe9 \\"A se\xe7\xe3o DADOS_BASICOS \xe9 reservada aos dados b\xe1sicos do candidato.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].paginaCodigo` para o item ou `grupos[i].paginaCodigo` para o grupo (nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`), em que `i` \xe9 a posi\xe7\xe3o na lista enviada. Nada \xe9 gravado. A confer\xeancia vale s\xf3 para o formul\xe1rio e o modelo de inscri\xe7\xe3o.","Na grava\xe7\xe3o dos itens, a recusa sai junto das demais recusas dos itens. Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Aponte o item ou o grupo para outra se\xe7\xe3o do formul\xe1rio. Os itens do conjunto b\xe1sico n\xe3o precisam ser enviados: o sistema os rep\xf5e na se\xe7\xe3o reservada."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);